content.text:
{
  "steps": [
    {
      "title": "დაკეტე წყალი",
      "text": "მოატრიალე ონკანი საათის ისრის მიმართულებით ბოლომდე. შემდეგ მეორეც დაკეტე.",
      "focus": ["p2", "p3"],
      "avoid": [],
      "markers": [],
      "arrows": [
        {"part": "p2", "type": "rotate", "dir": "cw"},
        {"part": "p3", "type": "rotate", "dir": "cw"}
      ],
      "tools": [],
      "warn": "ონკანებს ძალა არ დაატანო."
    },
    {
      "title": "ჩადგი ვედრო სიფონის ქვეშ",
      "text": "სიფონში წყალი დგას. გახსნისას ჩამოიღვრება, ამიტომ ვედრო ან ღრმა თასი პირდაპირ მის ქვეშ დადგი.",
      "focus": [],
      "avoid": [],
      "markers": [],
      "arrows": [],
      "tools": ["ვედრო ან ღრმა თასი"],
      "warn": "დასადგმელი ვედრო ან თასი ფოტოზე არ ჩანს და მინიჭებული ID არ აქვს."
    },
    {
      "title": "მოუშვი ქანჩი",
      "text": "ეს ქანჩი ჟონავს. ხელით მოუშვი საათის ისრის საწინააღმდეგოდ. პლასტმასისაა, გასაღები არ დაგჭირდება.",
      "focus": ["p4"],
      "avoid": ["p1"],
      "markers": [
        {"part": "p4", "label": "სავარაუდოდ ჟონავი შეერთება", "tone": "brand"}
      ],
      "arrows": [
        {"part": "p4", "type": "rotate", "dir": "ccw"}
      ],
      "tools": [],
      "warn": "არჩეულია მარჯვენა ქანჩი p4: ფოტოზე მის ქვედა კიდესთან წვეთი ჩანს. ეს გაჟონვის სავარაუდო ადგილია, თუმცა წყლის ზუსტი წყარო მხოლოდ ფოტოთი ვერ დასტურდება. მოშვებისას ქვედა მილს ხელი შეაშველე."
    },
    {
      "title": "შეამოწმე შუასადები",
      "text": "მოხსენი სიფონი და ნახე ქანჩის შიგნით რეზინის რგოლი. თუ დაბზარულია ან გვერდზეა გადაწეული, შეცვალე. ზომა: 40 მმ.",
      "focus": ["p5", "p4"],
      "avoid": [],
      "markers": [],
      "arrows": [],
      "tools": ["შესაბამისი ზომის ახალი შუასადები"],
      "warn": "p5 არის მოსახსნელი მილი, ხოლო p4 — შესამოწმებელი შუასადების სავარაუდო შეერთება. თავად შუასადები შიგნითაა და არ ჩანს; მისი ID არ არის მოცემული. 40 მმ ინსტრუქციაში მითითებული ზომაა და ფოტოთი არ დასტურდება — შეძენამდე გადაამოწმე. მილი ძალით არ მოქაჩო; ჯერ საჭირო შეერთებები გაათავისუფლე."
    },
    {
      "title": "მოუჭირე და შეამოწმე",
      "text": "ხელით მოუჭირე ბოლომდე, შემდეგ კიდევ მეოთხედი ბრუნი. გახსენი წყალი და ერთი წუთი დააკვირდი.",
      "focus": ["p4", "p2", "p3"],
      "avoid": [],
      "markers": [
        {"part": "p4", "label": "შეამოწმე წვეთები", "tone": "brand"}
      ],
      "arrows": [
        {"part": "p4", "type": "rotate", "dir": "cw"},
        {"part": "p2", "type": "rotate", "dir": "ccw"},
        {"part": "p3", "type": "rotate", "dir": "ccw"}
      ],
      "tools": [],
      "warn": "მოსაჭერ სამიზნედ კვლავ p4 არის ნავარაუდევი ხილული წვეთის მიხედვით. პლასტმასის ქანჩი ზედმეტად არ მოჭირო: დამატებითი მეოთხედი ბრუნი მხოლოდ მაშინ გააკეთე, თუ მწარმოებლის მითითება უშვებს. შემოწმებისას ნიჟარაში წყალიც გაუშვი; მხოლოდ ჩამკეტი ონკანების გახსნა სიფონს არ ამოწმებს."
    }
  ],
  "unknown_parts": [
    "ვედრო ან ღრმა თასი — ფოტოზე არ ჩანს.",
    "ქანჩის შიგნით არსებული რეზინის შუასადები — დაფარულია და ცალკე ID არ აქვს.",
    "ნიჟარის წყლის გასაშვები ონკანი — ფოტოზე არ ჩანს."
  ]
}
